#!/usr/bin/env node

/**
 * Page Assemble & Content Hook Script for Website Builder Skill.
 *
 * Automatically wraps minimal body/main HTML fragments generated by LLM
 * with the standard HTML boilerplate:
 * - Full <!doctype html> and <html lang="zh-CN">
 * - Standard <head> with Google Fonts, Bootstrap Icons, Swiper CSS, Tailwind CDN, and js/app.js
 * - Tailwind utility classes; w-full max-w-content mx-auto px-4 lg:px-6 keeps source semantics and uses explicit Tailwind utilities
 * - Pre-appended <header-component>
 * - Optional cart drawer (--cart=drawer), plus footer
 * - Standard CDN runtime scripts (jQuery, Swiper) and components/data scripts
 *
 * This minimizes LLM output tokens so models only need to return the core <body>/<main> content!
 *
 * Usage:
 *   1. From input file:
 *      node scripts/hook-page.mjs --input=./body.html --output=./dist/shop.html --title="Shop"
 *
 *   2. In-place wrapping (wraps fragment directly in target file):
 *      node scripts/hook-page.mjs --file=./dist/custom.html --title="Custom Page"
 *
 *   3. From inline content argument:
 *      node scripts/hook-page.mjs --content="<main>...</main>" --output=./dist/deal.html --title="Deals"
 *
 *   4. From stdin:
 *      type body.html | node scripts/hook-page.mjs --output=./dist/index.html --title="Home"
 */

import { spawn } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import fs from 'node:fs';
import path from 'node:path';

const args = process.argv.slice(2);
function getArg(name, fallback = '') {
  const match = args.find(a => a.startsWith(`--${name}=`));
  return match ? match.slice(name.length + 3) : fallback;
}

const targetFile = getArg('output') || getArg('file');
const inputFile = getArg('input');
const inlineContent = getArg('content');
const title = getArg('title', 'Online Store');
const lang = getArg('lang', 'en');
const noHeader = args.includes('--no-header');
const noFooter = args.includes('--no-footer');
const noCart = args.includes('--no-cart');
const cartMode = noCart ? 'none' : getArg('cart', 'page');
if (!['page', 'drawer', 'none'].includes(cartMode)) throw new Error('--cart must be page, drawer or none');
const hasCart = cartMode !== 'none' && fs.existsSync(path.resolve(path.dirname(targetFile || inputFile || './index.html'), 'components/cart.js'));
const enableLan = args.includes('--lan') || args.includes('--i18n');

function assembleHtml(bodyFragment, pageTitle = title) {
  // If fragment already has full html, return as is
  if (bodyFragment.includes('<!doctype html>') || bodyFragment.includes('<html')) {
    return bodyFragment;
  }

  // Extract any trailing <script> tags from body fragment to place near </body>
  let cleanBody = bodyFragment.trim();
  const scriptTags = [];
  cleanBody = cleanBody.replace(/<script\b[^>]*>([\s\S]*?)<\/script>/gi, (match) => {
    scriptTags.push(match);
    return '';
  }).trim();

  return `<!doctype html>
<html lang="${lang}">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${pageTitle}</title>

  <!-- Google Fonts: Noto Sans SC -->
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Noto+Sans+SC:wght@300;400;500;600;700&display=swap" rel="stylesheet">

  <!-- Bootstrap Icons (Cloudflare CDN) -->
  <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/bootstrap-icons/1.11.3/font/bootstrap-icons.min.css">

  <!-- Swiper CSS (Cloudflare CDN) -->
  <link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/Swiper/10.3.1/swiper-bundle.min.css">

  <!-- Tailwind CSS Play CDN -->
  <script src="https://cdn.tailwindcss.com"></script>

  <!-- Main Application Script & Tailwind Configuration -->
  <script src="js/app.js"></script>

</head>
<body class="m-0 bg-surface font-sans text-content min-h-screen flex flex-col antialiased">

  ${noHeader ? '' : '<!-- Global Header Component -->\n  <header-component></header-component>\n'}
  <!-- Main Page Content Hooked from Model Output -->
  ${cleanBody}

  ${hasCart && cartMode === 'drawer' && !/<cart-component\b/i.test(cleanBody) ? '<!-- Global Cart Drawer Component -->\n  <cart-component view-mode="drawer"></cart-component>\n' : ''}
  ${noFooter ? '' : '<!-- Global Footer Component -->\n  <footer-component></footer-component>\n'}
  <!-- Runtime Libraries (Cloudflare CDN) -->
  <script src="https://cdnjs.cloudflare.com/ajax/libs/jquery/3.7.1/jquery.min.js"></script>
  <script src="https://cdnjs.cloudflare.com/ajax/libs/Swiper/10.3.1/swiper-bundle.min.js"></script>

  <!-- Data Logic -->
  <script src="js/data.js"></script>
  ${enableLan ? '<script src="js/lan.js"></script>' : ''}

  <!-- Web Components -->
  <script src="components/header.js"></script>
  <script src="components/footer.js"></script>
  ${hasCart ? '<script src="components/cart.js"></script>' : ''}
  <script src="components/card.js"></script>

  ${scriptTags.length > 0 ? `<!-- Injected Page Scripts -->\n  ${scriptTags.join('\n  ')}` : ''}
</body>
</html>
`;
}

async function run() {
  let fragment = '';

  if (inlineContent) {
    fragment = inlineContent;
  } else if (inputFile) {
    fragment = fs.readFileSync(path.resolve(process.cwd(), inputFile), 'utf8');
  } else if (getArg('file')) {
    const p = path.resolve(process.cwd(), getArg('file'));
    if (fs.existsSync(p)) {
      fragment = fs.readFileSync(p, 'utf8');
    }
  } else if (!process.stdin.isTTY) {
    fragment = await new Promise((resolve) => {
      let data = '';
      process.stdin.on('data', chunk => data += chunk);
      process.stdin.on('end', () => resolve(data));
    });
  }

  if (!fragment.trim()) {
    console.error('Error: No body content provided to hook. Use --input=<file>, --content="...", or pipe to stdin.');
    process.exit(1);
  }

  const rawHtml = assembleHtml(fragment, title);
  const fullHtml = await new Promise((resolve,reject)=>{
    const child=spawn(process.execPath,[fileURLToPath(new URL('../../../dist/server/cli.js',import.meta.url))],{stdio:['pipe','pipe','pipe'],env:process.env});
    let output='',error='';child.stdout.on('data',data=>output+=data);child.stderr.on('data',data=>error+=data);
    child.on('error',reject);child.on('exit',code=>{if(code)return reject(new Error(error));try{resolve(JSON.parse(output).content);}catch(cause){reject(cause);}});
    child.stdin.end(JSON.stringify({action:'format',path:targetFile||'index.html',content:rawHtml}));
  });

  if (targetFile) {
    const outPath = path.resolve(process.cwd(), targetFile);
    fs.mkdirSync(path.dirname(outPath), { recursive: true });
    fs.writeFileSync(outPath, fullHtml.trim() + '\n', 'utf8');
    console.log(`[Hook Success] Assembled full HTML into: ${outPath}`);
  } else {
    // Print to stdout
    process.stdout.write(fullHtml);
  }
}

run().catch(err => {
  console.error('Hook error:', err);
  process.exit(1);
});
